--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters

local ElectricalTrigger = CS.ElectricalSystem.ElectricalTrigger
local Interrupter = CS.ElectricalSystem.ElectricalSwitch.Interrupter
local OnOff = CS.Game.OnOff



-- ========================================================


-- animator 上只有一个开关, 反复切换即可:
local _SwitchOn = Animator.StringToHash("SwitchOn")



-- ========================================================

function DS_Switcher:__init()
    self.controller = nil
end


function DS_Switcher:__delete()
end



function DS_Switcher:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end


function DS_Switcher:Start()
    KTool.SetActive(self.controller.gameObject, true)

    self.isInit = false
    assert( self.animator and self.electricalTrigger )
    --assert( self.interrupter )

    assert( self.bindGearHint2InterrupterBH )
    self.bindGearHint2Interrupter = DreamSpaceLuaUtils.GetLuaScr(self.bindGearHint2InterrupterBH.gameObject, "Game.DreamSpace.Level1.BindGearHint2Interrupter" )
    assert( self.bindGearHint2Interrupter )

    self.bindGearHint2Interrupter.DoBeforeTriggerInterrupter = Bind(self, self.DoBeforeTriggerInterrupter )


    -- 不再需要了
    --self.interrupter.WhenOnTriggerEnter = Bind(self, self.WhenOnTriggerEnter)
    --interrupter.WhenOnTriggerExit = WhenOnTriggerExit;


    self.animator:SetBool( _SwitchOn, (self.electricalTrigger.isSwitchOn == OnOff.On) )

    self.isInit = true
end




function DS_Switcher:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



function DS_Switcher:DoBeforeTriggerInterrupter()
    
    if KTool.IsAnimatorPlaying(self.animator) == false then


        local oldVal = self.animator:GetBool( _SwitchOn ) -- bool
        self.animator:SetBool( _SwitchOn, not oldVal )

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.3 ))

        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.electricBrake )  -- 播放 电路开关 启动 声音:

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))

        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.electricCurrent )

        -- todo: 比较好的方法是在 animation clip 里安插 event, 然后得知何时结束
        -- 参见 PlayerVCamAnimationEvent
        --cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 )) -- 先手写一个动画播放时间...
    end

end



